package com.fooddelivery.user.controller;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import com.fooddelivery.user.dto.UserDto;import com.fooddelivery.user.service.UserService;@RestController @RequestMapping("/api/users") public class UserController{private final UserService s;public UserController(UserService s){this.s=s;}@PostMapping public ResponseEntity<UserDto> create(@RequestBody UserDto d){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(d));}@GetMapping public List<UserDto> all(){return s.all();}@GetMapping("/{id}") public UserDto get(@PathVariable Long id){return s.get(id);}}
